To stream a structured object for real-time UI rendering, you need to:

1. **On the server**: Use `streamText` with `Output.object()` to generate the object stream
2. **On the client**: Use the `useObject` hook to consume the stream and update your UI

Here's a complete example:

### Server Component (API Route)
```ts title='app/api/object/route.ts'
import { createTextStreamResponse, Output, streamText, toTextStream } from 'ai';
import { z } from 'zod';

export async function POST(req: Request) {
  const context = await req.json();

  const result = streamText({
    model: "anthropic/claude-sonnet-5.5",
    output: Output.object({
      schema: z.object({
        recipe: z.object({
          name: z.string(),
          ingredients: z.array(z.string()),
          steps: z.array(z.string()),
        }),
      }),
    }),
    prompt: `Generate a lasagna recipe in this context: ${context}`,
  });

  return createTextStreamResponse({
    stream: toTextStream({ stream: result.stream }),
  });
}
```

### Client Component (UI)
```tsx title='app/page.tsx'
'use client';

import { useObject } from '@ai-sdk/react';
import { z } from 'zod';

const recipeSchema = z.object({
  recipe: z.object({
    name: z.string(),
    ingredients: z.array(z.string()),
    steps: z.array(z.string()),
  }),
});

export default function RecipeGenerator() {
  const { object, submit, isLoading, stop } = useObject({
    api: '/api/object',
    schema: recipeSchema,
  });

  return (
    <div>
      <button
        onClick={() => submit('Generate a detailed lasagna recipe')}
        disabled={isLoading}
      >
        {isLoading ? 'Generating...' : 'Generate Recipe'}
      </button>

      {isLoading && (
        <div>
          <button type="button" onClick={stop}>
            Stop
          </button>
        </div>
      )}

      {object?.recipe && (
        <div>
          <h2>{object.recipe.name}</h2>
          <h3>Ingredients:</h3>
          <ul>
            {object.recipe.ingredients.map((ingredient, i) => (
              <li key={i}>{ingredient}</li>
            ))}
          </ul>
          <h3>Steps:</h3>
          <ol>
            {object.recipe.steps.map((step, i) => (
              <li key={i}>{step}</li>
            ))}
          </ol>
        </div>
      )}
    </div>
  );
}
```

Key points:
- The server streams the partial object using `streamText` with `Output.object()`
- The client uses `useObject` which provides `object` (the accumulated result), `isLoading` state, and `stop` function
- The UI updates automatically as each part of the object is generated [2,5,8]

