To ensure the response is saved even when the user closes the browser tab during streaming, call `consumeStream()` on the result. This removes backpressure and lets the stream complete on the server, triggering your save logic via `onEnd`:

```tsx
import { streamText, convertToModelMessages, createUIMessageStreamResponse, toUIMessageStream } from 'ai';
import { saveChat } from '@util/chat-store';

export async function POST(req: Request) {
  const { messages, chatId } = await req.json();

  const result = streamText({
    model,
    messages: await convertToModelMessages(messages),
  });

  // Consume the stream to ensure it runs to completion & triggers onEnd
  // even when the client disconnects:
  result.consumeStream(); // no await

  return createUIMessageStreamResponse({
    stream: toUIMessageStream({
      stream: result.stream,
      originalMessages: messages,
      onEnd: ({ messages }) => {
        saveChat({ chatId, messages });
      },
    }),
  });
}
```

